## Classes and errors

```javascript-norun
class Account {
  #balance = 0;                                   // private field
  constructor(owner) { this.owner = owner; }
  get balance() { return this.#balance; }         // getter
  static from(data) { return new Account(data.owner); }
}
class Savings extends Account { constructor(o) { super(o); } }

class ValidationError extends Error {
  constructor(message) { super(message); this.name = "ValidationError"; }
}
try { risky(); } catch (err) { if (!(err instanceof ValidationError)) throw err; } finally { cleanUp(); }
```

## Iterators and modules

```javascript-norun
function* range(a, b) { for (let i = a; i < b; i++) yield i; }
for (const x of range(0, 3)) console.log(x);

export function format(x) { }          // named export
export default class Cart { }          // default export
import Cart, { format } from "./cart.js";
const { chart } = await import("./chart.js");   // dynamic import
```

## Asynchronous code

```javascript-norun
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

async function load(url) {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  return response.json();
}

try { const data = await load("/api/items"); } catch (err) { console.error(err); }
const [a, b] = await Promise.all([load("/a"), load("/b")]);   // in parallel
for (const id of ids) await process(id);                      // one at a time
```

| Combinator | Result |
|---|---|
| `Promise.all` | All values in order; rejects at the first error |
| `Promise.allSettled` | `{ status, value \| reason }` for each; never rejects |
| `Promise.race` | The first to settle |
| `Promise.any` | The first to fulfil |

## TypeScript

```typescript-norun
let title: string = "Dune";
function f(x: number, label?: string): string { return `${label ?? ""}${x}`; }
interface User { readonly id: number; name: string; email?: string }
type Id = string | number;
type Shape = { kind: "circle"; r: number } | { kind: "rect"; w: number; h: number };
function first<T>(items: T[]): T | undefined { return items[0]; }
function pluck<T, K extends keyof T>(items: T[], key: K): T[K][] { return items.map(i => i[key]); }
function isUser(x: unknown): x is User { return typeof x === "object" && x !== null && "name" in x; }
const LEVELS = ["low", "high"] as const; type Level = (typeof LEVELS)[number];
```

| Utility | Meaning |
|---|---|
| `Partial<T>`, `Required<T>`, `Readonly<T>` | All optional / required / readonly |
| `Pick<T, K>`, `Omit<T, K>` | Only / all but these keys |
| `Record<K, V>` | Object with keys K and values V |
| `ReturnType<typeof f>`, `Awaited<P>` | A function's result, a promise's value |

